content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  text-align: center;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.control-panel {
  background: var(--card-bg);
  padding: 20px 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.control-panel h2 {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-main);
}

.checkbox-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.store-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 0.95rem;
  font-weight: 500;
  user-select: none;
  padding: 6px 12px;
  border-radius: 6px;
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  transition: all 0.2s ease;
}

.store-checkbox:hover {
  background-color: #f1f5f9;
}

.store-checkbox input[type="checkbox"] {
  cursor: pointer;
  width: 16px;
  height: 16px;
  accent-color: var(--primary-color);
}

.chart-wrapper {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: 100%;
  height: 450px;
}

.table-wrapper {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow-x: auto;
}

.table-wrapper h2 {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 16px;
  color: var(--text-main);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.data-table th,
.data-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.data-table th {
  background-color: #f8fafc;
  font-weight: 600;
  color: var(--text-main);
}

.data-table tbody tr:hover {
  background-color: #f8fafc;
}

.data-table tbody tr:last-child td {
  border-bottom: none;
}

@media (max-width: 768px) {
  .control-panel {
    flex-direction: column;
    align-items: flex-start;
  }

  .checkbox-group {
    width: 100%;
    justify-content: space-between;
  }

  .chart-wrapper {
    height: 350px;
  }
}

export interface MonthlyData {
  month: string;
  渋谷店: number;
  新宿店: number;
  池袋店: number;
}

export interface StoreVisibility {
  渋谷店: boolean;
  新宿店: boolean;
  池袋店: boolean;
}

import { useState } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlyData, StoreVisibility } from './types';
import './index.css';

const initialData: MonthlyData[] = [
  { month: '1月', 渋谷店: 1200, 新宿店: 1500, 池袋店: 1100 },
  { month: '2月', 渋谷店: 1300, 新宿店: 1600, 池袋店: 1250 },
  { month: '3月', 渋谷店: 1500, 新宿店: 1900, 池袋店: 1400 },
  { month: '4月', 渋谷店: 1400, 新宿店: 1750, 池袋店: 1350 },
  { month: '5月', 渋谷店: 1600, 新宿店: 2000, 池袋店: 1550 },
  { month: '6月', 渋谷店: 1550, 新宿店: 1950, 池袋店: 1500 },
  { month: '7月', 渋谷店: 1800, 新宿店: 2300, 池袋店: 1700 },
  { month: '8月', 渋谷店: 1900, 新宿店: 2400, 池袋店: 1800 },
  { month: '9月', 渋谷店: 1650, 新宿店: 2100, 池袋店: 1600 },
  { month: '10月', 渋谷店: 1700, 新宿店: 2150, 池袋店: 1650 },
  { month: '11月', 渋谷店: 1750, 新宿店: 2200, 池袋店: 1700 },
  { month: '12月', 渋谷店: 2100, 新宿店: 2600, 池袋店: 2000 },
];

export default function App() {
  const [visibility, setVisibility] = useState<StoreVisibility>({
    渋谷店: true,
    新宿店: true,
    池袋店: true,
  });

  const handleCheckboxChange = (store: keyof StoreVisibility) => {
    setVisibility((prev) => ({
      ...prev,
      [store]: !prev[store],
    }));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>店舗別月別来客数比較</h1>
        <p>渋谷店、新宿店、池袋店の月ごとの来客数データをグラフと表で確認できます。</p>
      </header>

      <div className="control-panel">
        <h2>表示店舗の切り替え</h2>
        <div className="checkbox-group">
          <label className="store-checkbox">
            <input
              type="checkbox"
              checked={visibility.渋谷店}
              onChange={() => handleCheckboxChange('渋谷店')}
            />
            渋谷店
          </label>
          <label className="store-checkbox">
            <input
              type="checkbox"
              checked={visibility.新宿店}
              onChange={() => handleCheckboxChange('新宿店')}
            />
            新宿店
          </label>
          <label className="store-checkbox">
            <input
              type="checkbox"
              checked={visibility.池袋店}
              onChange={() => handleCheckboxChange('池袋店')}
            />
            池袋店
          </label>
        </div>
      </div>

      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={initialData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
            <XAxis dataKey="month" stroke="#64748b" />
            <YAxis stroke="#64748b" />
            <Tooltip />
            <Legend />
            {visibility.渋谷店 && (
              <Line
                type="monotone"
                dataKey="渋谷店"
                stroke="#3b82f6"
                strokeWidth={2}
                activeDot={{ r: 8 }}
              />
            )}
            {visibility.新宿店 && (
              <Line
                type="monotone"
                dataKey="新宿店"
                stroke="#10b981"
                strokeWidth={2}
                activeDot={{ r: 8 }}
              />
            )}
            {visibility.池袋店 && (
              <Line
                type="monotone"
                dataKey="池袋店"
                stroke="#f59e0b"
                strokeWidth={2}
                activeDot={{ r: 8 }}
              />
            )}
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div className="table-wrapper">
        <h2>月別来客数データ一覧</h2>
        <table className="data-table">
          <thead>
            <tr>
              <th>月</th>
              <th>渋谷店</th>
              <th>新宿店</th>
              <th>池袋店</th>
            </tr>
          </thead>
          <tbody>
            {initialData.map((row) => (
              <tr key={row.month}>
                <td>{row.month}</td>
                <td>{row.渋谷店.toLocaleString()} 人</td>
                <td>{row.新宿店.toLocaleString()} 人</td>
                <td>{row.池袋店.toLocaleString()} 人</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
